def compute(vars):
    original_note_amount = vars["v1"]
    outstanding_balance = vars["v2"]
    received_amount = original_note_amount - outstanding_balance

    return {
        "value": received_amount,
        "trace": {
            "original_note_amount": original_note_amount,
            "outstanding_balance": outstanding_balance,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "monetary"
            }
        }
    }
